scripts.support-store:
import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';
import { rosterStore } from '@bendyline/gezel-sdk/stores';

export const meta = defineScript({
  name: 'support-store',
  description:
    "Read and update the support desk: its tickets (tickets.json) and the help articles in kb/. action:'status' for what needs a reply, what waits on the customer and the questions no help article answers; 'add' to log a ticket (the same subject from the same customer updates the open ticket, never duplicates it); 'reply' to save a suggested reply and the article or gap behind it; 'set_status' to move a ticket; 'save_article' to write a help article in kb/ and close the gap it answers; 'list' for every ticket.",
  inputs: {
    action: {
      type: 'string',
      description: "One of 'status', 'add', 'reply', 'set_status', 'save_article', or 'list'.",
      required: true,
    },
    id: { type: 'string', description: "Ticket id, e.g. 'tk-3'." },
    subject: {
      type: 'string',
      description: "The ticket's subject, e.g. 'Book arrived with a torn cover'. Also finds it when no id is given.",
    },
    customer: { type: 'string', description: 'Who wrote in.' },
    channel: { type: 'string', description: 'email, phone, chat, social, in-person, or other.' },
    category: {
      type: 'string',
      description: 'order, delivery, billing, product, account, business, complaint, or other.',
    },
    priority: { type: 'string', description: 'normal, urgent, or low.' },
    message: { type: 'string', description: 'What the customer asked, in their words.' },
    receivedAt: { type: 'string', description: 'The day it came in, YYYY-MM-DD (default today).' },
    reply: { type: 'string', description: 'The suggested reply, ready for the person to send.' },
    article: { type: 'string', description: "The help article the reply draws on, e.g. 'kb/refunds.md'." },
    gap: {
      type: 'string',
      description: "A short topic for a question no help article answers yet, e.g. 'wholesale terms'.",
    },
    status: { type: 'string', description: 'For set_status: new, open, waiting, or resolved.' },
    note: { type: 'string', description: 'What happened.' },
    title: { type: 'string', description: "For save_article: the article's title." },
    body: { type: 'string', description: 'For save_article: the article in markdown.' },
    topic: { type: 'string', description: 'For save_article: the gap it answers, as the status names it.' },
  },
  outputs: {
    needsReply: { type: 'number', description: 'Tickets that are new or open.' },
    waiting: { type: 'number', description: 'Tickets waiting on the customer.' },
    gaps: { type: 'number', description: 'Questions no help article answers yet.' },
    summary: { type: 'string', description: 'The desk picture, or the listing.' },
  },
  requires: ['workspace.read', 'workspace.write'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

// ── support-rules-start ──
// Pure derivations: a ticket's age in local calendar days, the reply queue
// (urgent first, then oldest), the knowledge-base gaps grouped by topic, and
// the desk picture the crew reads. Kept self-contained between these
// sentinels so unit tests execute the shipped bytes.
var DAY_MS = 86400000;
var STAGES = ['new', 'open', 'waiting', 'resolved'];
var CATEGORIES = ['order', 'delivery', 'billing', 'product', 'account', 'business', 'complaint', 'other'];
var CHANNELS = ['email', 'phone', 'chat', 'social', 'in-person', 'other'];
var PRIORITIES = ['normal', 'urgent', 'low'];
var CATEGORY_ALIASES = {
  orders: 'order', shipping: 'delivery', shipment: 'delivery', damaged: 'delivery', refund: 'billing', refunds: 'billing',
  payment: 'billing', invoice: 'billing', charge: 'billing', question: 'product', products: 'product', login: 'account',
  download: 'account', subscription: 'account', wholesale: 'business', partnership: 'business', press: 'business',
  booking: 'business', feedback: 'complaint', complaints: 'complaint',
};

function pad(n) {
  return n < 10 ? '0' + n : String(n);
}
function localDay(ms) {
  var d = new Date(ms);
  return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
}
function normalizeDate(text) {
  var raw = String(text || '').trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) return raw;
  var parsed = Date.parse(raw);
  return isFinite(parsed) ? localDay(parsed) : null;
}
function ageDays(day, nowMs) {
  var start = Date.parse(String(day || '').slice(0, 10) + 'T00:00:00');
  if (!isFinite(start)) return 0;
  var today = Date.parse(localDay(nowMs) + 'T00:00:00');
  return Math.max(0, Math.round((today - start) / DAY_MS));
}
function age(days) {
  return days === 0 ? 'came in today' : days === 1 ? '1 day old' : days + ' days old';
}
function categoryOf(text) {
  var key = String(text || '').trim().toLowerCase();
  if (CATEGORIES.indexOf(key) >= 0) return key;
  return CATEGORY_ALIASES[key] || null;
}
function topicKey(text) {
  return String(text || '').trim().toLowerCase().replace(/\s+/g, ' ');
}
function sameTopic(a, b) {
  var x = topicKey(a), y = topicKey(b);
  return !!x && !!y && (x === y || x.indexOf(y) >= 0 || y.indexOf(x) >= 0);
}
function slug(text) {
  var s = String(text || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60).replace(/-+$/, '');
  return s || 'article';
}
function articlePath(text) {
  var p = String(text || '').trim().replace(/\\/g, '/').replace(/^\.?\/+/, '');
  if (!p || p.split('/').indexOf('..') >= 0) return null;
  return p.indexOf('kb/') === 0 ? p : 'kb/' + p;
}
function urgency(record) {
  var p = record.fields && record.fields.priority;
  return p === 'urgent' ? 0 : p === 'low' ? 2 : 1;
}
function oldestFirst(a, b) {
  return String(a.fields.receivedAt || '').localeCompare(String(b.fields.receivedAt || '')) || String(a.id).localeCompare(String(b.id), undefined, { numeric: true });
}
function replyQueue(records) {
  return records
    .filter(function (r) { return r.status === 'new' || r.status === 'open'; })
    .slice()
    .sort(function (a, b) { return urgency(a) - urgency(b) || oldestFirst(a, b); });
}
function waitingList(records) {
  return records.filter(function (r) { return r.status === 'waiting'; }).slice().sort(oldestFirst);
}
// A gap is a question no help article answers yet: a ticket with a kbGap
// topic and no kbArticle. Tickets are grouped by topic, the most asked first.
function openGaps(records) {
  var groups = [];
  records.forEach(function (r) {
    var f = r.fields || {};
    if (!f.kbGap || f.kbArticle) return;
    var group = groups.find(function (g) { return topicKey(g.topic) === topicKey(f.kbGap); });
    if (!group) {
      group = { topic: String(f.kbGap).trim(), tickets: [] };
      groups.push(group);
    }
    group.tickets.push(r);
  });
  return groups.sort(function (a, b) { return b.tickets.length - a.tickets.length || a.topic.localeCompare(b.topic); });
}
function excerpt(text, length) {
  var t = String(text || '').replace(/\s+/g, ' ').trim();
  return t.length > length ? t.slice(0, length - 1).trim() + '…' : t;
}
// The gap topic already on the desk that a new mention means, so one question keeps one name.
function knownTopic(records, text) {
  var hit = openGaps(records).find(function (g) { return sameTopic(g.topic, text); });
  return hit ? hit.topic : String(text || '').trim();
}
function line(record, nowMs, withMessage) {
  var f = record.fields || {};
  var active = record.status === 'new' || record.status === 'open';
  return (
    f.subject +
    ' (' + record.id + ', ' + (f.category || 'other') + (f.customer ? ', from ' + f.customer : '') + ', ' + age(ageDays(f.receivedAt, nowMs)) + ')' +
    (f.priority === 'urgent' ? ', urgent' : '') +
    (active ? ', ' + record.status : '') +
    (f.suggestedReply ? ', reply drafted' : active ? ', no reply drafted yet' : '') +
    (f.kbArticle ? ', help article ' + f.kbArticle : f.kbGap ? ', no help article for "' + f.kbGap + '"' : '') +
    (withMessage && f.message ? ': "' + excerpt(f.message, 140) + '"' : '')
  );
}
function picture(records, articles, nowMs) {
  var counts = {};
  STAGES.forEach(function (s) { counts[s] = 0; });
  records.forEach(function (r) { counts[r.status] = (counts[r.status] || 0) + 1; });
  var queue = replyQueue(records);
  var waiting = waitingList(records);
  var gaps = openGaps(records);
  var parts = [
    records.length + (records.length === 1 ? ' ticket' : ' tickets') + ' on the desk: ' + counts.new + ' new, ' + counts.open + ' open, ' +
      counts.waiting + ' waiting on the customer, ' + counts.resolved + ' resolved.',
  ];
  parts.push(
    queue.length
      ? 'Needs a reply, urgent first, then oldest: ' + queue.map(function (r) { return line(r, nowMs, true); }).join(' | ') + '.'
      : 'Nothing needs a reply.',
  );
  if (waiting.length) parts.push('Waiting on the customer: ' + waiting.map(function (r) { return line(r, nowMs, false); }).join(' | ') + '.');
  parts.push(
    gaps.length
      ? 'Questions no help article answers yet, most asked first: ' +
          gaps.map(function (g) {
            return '"' + g.topic + '" (' + g.tickets.length + (g.tickets.length === 1 ? ' ticket: ' : ' tickets: ') + g.tickets.map(function (r) { return r.id; }).join(', ') + ')';
          }).join(' | ') + '.'
      : 'No knowledge-base gaps recorded.',
  );
  parts.push(articles.length ? 'Help articles in kb/: ' + articles.join(', ') + '.' : 'No help articles in kb/ yet.');
  return { needsReply: queue.length, waiting: waiting.length, gaps: gaps.length, summary: parts.join(' ') };
}
// ── support-rules-end ──

const tickets = rosterStore(gezel.fs, 'tickets.json', {
  stages: ['new', 'open', 'waiting', 'resolved'],
  idPrefix: 'tk',
});

async function articles(): Promise<string[]> {
  try {
    return (await gezel.fs.list('kb'))
      .filter((e) => !e.isDirectory)
      .map((e) => 'kb/' + e.name)
      .sort();
  } catch {
    return [];
  }
}

// By id, or by (partial) subject; a missing id is tried as a subject too.
async function resolve(): Promise<string> {
  const all = await tickets.list();
  if (input.id) {
    const byId = all.find((r) => r.id === input.id!.trim().toLowerCase());
    if (byId) return byId.id;
  }
  const text = input.subject ?? input.id;
  if (text) {
    const wanted = text.trim().toLowerCase();
    const exact = all.filter((r) => String(r.fields.subject ?? '').toLowerCase() === wanted);
    if (exact.length === 1) return exact[0]!.id;
    let partial = all.filter((r) => String(r.fields.subject ?? '').toLowerCase().includes(wanted));
    if (partial.length > 1) {
      const active = partial.filter((r) => r.status !== 'resolved');
      if (active.length === 1) return active[0]!.id;
      partial = active.length ? active : partial;
      throw new Error("More than one ticket matches '" + text + "': " + partial.map((r) => r.id + ' ' + String(r.fields.subject)).join(', ') + '. Pass id.');
    }
    if (partial.length === 1) return partial[0]!.id;
  }
  throw new Error(
    "Pass 'id' (e.g. 'tk-3') or the ticket's 'subject'. Tickets: " +
      (all.map((r) => r.id + ' ' + String(r.fields.subject)).join(', ') || 'none yet') + '.',
  );
}

const LABELS: Record<string, string> = {
  new: 'back to new',
  open: 'open',
  waiting: 'waiting on the customer',
  resolved: 'resolved',
};
let note = '';

if (input.action === 'add') {
  const subject = (input.subject ?? '').trim();
  if (!subject) throw new Error("add needs 'subject'.");
  const receivedAt = input.receivedAt ? normalizeDate(input.receivedAt) : null;
  if (input.receivedAt && !receivedAt) throw new Error("receivedAt must be a date, e.g. '2026-11-02'.");
  const category = categoryOf(input.category);
  const channel = CHANNELS.includes(String(input.channel)) ? String(input.channel) : undefined;
  const priority = PRIORITIES.includes(String(input.priority)) ? String(input.priority) : undefined;
  const who = (input.customer ?? '').trim().toLowerCase();
  const all = await tickets.list();
  const existing = all.find(
    (r) =>
      r.status !== 'resolved' &&
      String(r.fields.subject ?? '').toLowerCase() === subject.toLowerCase() &&
      (!who || !r.fields.customer || String(r.fields.customer).toLowerCase() === who),
  );
  const fields: Record<string, unknown> = {
    ...(input.customer && !existing?.fields.customer ? { customer: input.customer.trim() } : {}),
    ...(channel ? { channel } : {}),
    ...(category ? { category } : {}),
    ...(priority ? { priority } : {}),
    ...(input.message ? { message: input.message.trim() } : {}),
    ...(receivedAt ? { receivedAt } : {}),
    ...(input.gap?.trim() ? { kbGap: knownTopic(all, input.gap) } : {}),
  };
  if (existing) {
    await tickets.update(existing.id, { fields });
    note = 'Updated ' + existing.id + ' (' + String(existing.fields.subject) + ').';
  } else {
    const record = await tickets.add({
      status: 'new',
      fields: {
        subject,
        category: 'other',
        channel: 'other',
        priority: 'normal',
        receivedAt: localDay(Date.now()),
        ...fields,
      },
    });
    note = 'Logged ' + record.id + ': ' + subject + '.';
  }
} else if (input.action === 'reply') {
  if (!input.reply?.trim() && !input.gap?.trim() && !input.article?.trim()) {
    throw new Error("reply needs 'reply' (the suggested reply), 'article' or 'gap'.");
  }
  const article = input.article ? articlePath(input.article) : null;
  if (input.article && !article) throw new Error("article must be a path inside kb/, e.g. 'kb/refunds.md'.");
  const id = await resolve();
  const record = (await tickets.get(id))!;
  const gap = input.gap?.trim() ? knownTopic(await tickets.list(), input.gap) : '';
  await tickets.update(id, {
    fields: {
      ...(input.reply?.trim() ? { suggestedReply: input.reply.trim() } : {}),
      ...(article ? { kbArticle: article } : {}),
      ...(gap ? { kbGap: gap } : {}),
    },
  });
  if (record.status === 'new' && input.reply?.trim()) await tickets.transition(id, 'open', { note: 'Reply drafted' });
  note =
    (input.reply?.trim() ? 'Saved a suggested reply on ' : 'Updated ') + String(record.fields.subject) + ' (' + id + ')' +
    (article ? ', drawn from ' + article : '') +
    (gap && !article ? '; noted the gap "' + gap + '"' : '') + '.';
} else if (input.action === 'set_status') {
  const status = String(input.status ?? '').trim().toLowerCase();
  if (!STAGES.includes(status)) throw new Error("set_status needs status 'new', 'open', 'waiting' or 'resolved'.");
  const id = await resolve();
  const record = (await tickets.get(id))!;
  await tickets.transition(id, status, input.note ? { note: input.note } : {});
  if (status === 'resolved') await tickets.update(id, { fields: { resolvedAt: localDay(Date.now()) } });
  note = String(record.fields.subject) + ' (' + id + ') is ' + LABELS[status] + '.';
} else if (input.action === 'save_article') {
  const title = (input.title ?? '').trim();
  const body = (input.body ?? '').trim();
  if (!title || !body) throw new Error("save_article needs 'title' and 'body' (markdown).");
  const path = 'kb/' + slug(title) + '.md';
  await gezel.fs.write(path, (/^#\s/.test(body) ? body : '# ' + title + '\n\n' + body) + '\n');
  let closed = 0;
  if (input.topic?.trim()) {
    for (const r of await tickets.list()) {
      if (r.fields.kbGap && !r.fields.kbArticle && sameTopic(r.fields.kbGap, input.topic)) {
        await tickets.update(r.id, { fields: { kbArticle: path } });
        closed += 1;
      }
    }
  }
  note =
    'Saved ' + path +
    (closed ? '; it answers the "' + input.topic!.trim() + '" gap on ' + closed + (closed === 1 ? ' ticket' : ' tickets') : input.topic?.trim() ? '; no open gap matched "' + input.topic.trim() + '"' : '') + '.';
} else if (input.action !== 'status' && input.action !== 'list') {
  throw new Error("Unknown action '" + input.action + "'. Use status, add, reply, set_status, save_article, or list.");
}

const records = await tickets.list();
const kb = await articles();
const now = Date.now();
const view = picture(records, kb, now);

gezel.output({
  needsReply: view.needsReply,
  waiting: view.waiting,
  gaps: view.gaps,
  summary:
    input.action === 'list'
      ? records.map((r) => '[' + r.status + '] ' + line(r, now, true)).join('\n') || 'No tickets yet.'
      : (note ? note + ' ' : '') + view.summary,
});

reaction.prompt:
The person just moved a ticket on the support desk page. The desk now reads (its first sentence is what changed):
{{output.summary}}
In two short sentences, confirm what changed and name the next ticket that needs a reply, and whether its reply is drafted. Do not call tools.
